def ev(s):
    s = s.strip().rstrip('.').strip()
    s = re.sub(r'(?<=[\d)])\s*\(', '*(', s)
    s = re.sub(r'\)\s*(?=\d)', ')*', s)
    if not s or not ok_expr.match(s) or s.count('(') != s.count(')'):
        return None
    try:
